it('should apply default prefix weight when only fuzzy is provided', () => {
  const result = search(query, { weights: { fuzzy: 0.8 } });
  // Assert that fuzzy weight is 0.8 and prefix weight is 0.375 (default)
  expect(result.weights.fuzzy).toBe(0.8);
  expect(result.weights.prefix).toBe(0.375);
});

it('should apply default fuzzy weight when only prefix is provided', () => {
  const result = search(query, { weights: { prefix: 0.5 } });
  // Assert that prefix weight is 0.5 and fuzzy weight is 0.45 (default)
  expect(result.weights.prefix).toBe(0.5);
  expect(result.weights.fuzzy).toBe(0.45);
});

it('should use both weights when both are provided', () => {
  const result = search(query, { weights: { fuzzy: 0.9, prefix: 0.6 } });
  expect(result.weights.fuzzy).toBe(0.9);
  expect(result.weights.prefix).toBe(0.6);
});

it('should apply all default weights when weights is undefined', () => {
  const result = search(query, { weights: undefined });
  expect(result.weights.fuzzy).toBe(0.45);
  expect(result.weights.prefix).toBe(0.375);
});

it('should apply all default weights when weights is null', () => {
  const result = search(query, { weights: null });
  expect(result.weights.fuzzy).toBe(0.45);
  expect(result.weights.prefix).toBe(0.375);
});

it('should apply all default weights when weights is empty object', () => {
  const result = search(query, { weights: {} });
  expect(result.weights.fuzzy).toBe(0.45);
  expect(result.weights.prefix).toBe(0.375);
});

it('should apply defaults for explicit undefined values', () => {
  const result1 = search(query, { weights: { fuzzy: undefined, prefix: 0.5 } });
  expect(result1.weights.fuzzy).toBe(0.45);
  expect(result1.weights.prefix).toBe(0.5);

  const result2 = search(query, { weights: { fuzzy: 0.8, prefix: undefined } });
  expect(result2.weights.fuzzy).toBe(0.8);
  expect(result2.weights.prefix).toBe(0.375);
});

it('should accept zero as valid weight value', () => {
  const result = search(query, { weights: { fuzzy: 0, prefix: 0 } });
  expect(result.weights.fuzzy).toBe(0);
  expect(result.weights.prefix).toBe(0);
});

it('should accept one as valid weight value', () => {
  const result = search(query, { weights: { fuzzy: 1, prefix: 1 } });
  expect(result.weights.fuzzy).toBe(1);
  expect(result.weights.prefix).toBe(1);
});

// Type-level test (may require ts-expect-error or similar)
it('should compile with partial weights objects', () => {
  // These should all compile without TypeScript errors
  search(query, { weights: { fuzzy: 0.8 } });
  search(query, { weights: { prefix: 0.5 } });
  search(query, { weights: {} });
  search(query, { weights: { fuzzy: 0.8, prefix: 0.5 } });
});

